uint16_t Display::screenWidth() const {
    return DISPLAY_CLASS::WIDTH;
}

uint16_t Display::screenHeight() const {
    return DISPLAY_CLASS::HEIGHT;
}

void Display::printNumberLabeled(float value, int integerPartPadding, const char* label) {
    char str[16];

    mU8g2Fonts.setFont(LARGE_FONT);
    mU8g2Fonts.printf("%*.0f", integerPartPadding, value); // print integer part
    mU8g2Fonts.setFont(SMALL_FONT);
    int x = mU8g2Fonts.getCursorX();
    int y = mU8g2Fonts.getCursorY();
    snprintf(str, 16, "%.1f", value);
    mU8g2Fonts.print(strchr(str, '.')); // print float part
    mU8g2Fonts.setCursor(x + 2 * mSmallFontWidth - 2 * mLabelFontWidth, mU8g2Fonts.getCursorY() - LABEL_OFFSET_Y); // set label position
    mU8g2Fonts.setFont(LABEL_FONT);
    mU8g2Fonts.print(label); // print label
    mU8g2Fonts.setCursor(mU8g2Fonts.getCursorX(), y);
    mU8g2Fonts.setFont(LARGE_FONT);
}

void Display::alignCursorCenter(int width) {
    mU8g2Fonts.setCursor((screenWidth() - width) / 2, mU8g2Fonts.getCursorY());
}

void Display::alignCursorLeft() {
    mU8g2Fonts.setCursor(0, mU8g2Fonts.getCursorY());
}

void Display::alignCursorRight(int width) {
    mU8g2Fonts.setCursor(screenWidth() - width, mU8g2Fonts.getCursorY());
}

void Display::printCenter(const char *str) {
    int16_t width = getUTF8Width(str);
    mU8g2Fonts.setCursor((screenWidth() - width) / 2, getCursorY());
    print(str);
}
